package dev.dsh.remotehosts.core;

import android.security.keystore.KeyGenParameterSpec;
import android.security.keystore.KeyProperties;

import java.io.IOException;
import java.nio.ByteBuffer;
import java.security.GeneralSecurityException;
import java.security.KeyStore;
import java.security.UnrecoverableKeyException;
import java.util.Arrays;

import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import javax.crypto.spec.GCMParameterSpec;

/**
 * AES-256-GCM envelope encryption for the on-disk host store.
 *
 * The key is generated by and lives inside the Android Keystore (alias
 * {@value #KEY_ALIAS}, non-exportable, no user-authentication requirement so the
 * foreground service can decrypt after an unlock). Every write gets a fresh
 * random 12-byte IV from the Keystore provider.
 *
 * File format (docs/app-spec.md §4):
 *
 * <pre>
 *   MAGIC (4 bytes "DSHE") | VERSION (1 byte) | IV (12 bytes) | ciphertext + GCM tag
 * </pre>
 *
 * The plaintext/ciphertext never leaves memory unencrypted for the host store;
 * exception messages from this class carry no key material.
 */
public final class SecretBox {

    private static final String KEYSTORE_TYPE = "AndroidKeyStore";
    private static final String KEY_ALIAS = "dsh-mobile-store";
    private static final String TRANSFORMATION = "AES/GCM/NoPadding";

    /** 4-byte envelope magic ("DSH Encrypted"). */
    private static final byte[] MAGIC = {'D', 'S', 'H', 'E'};
    private static final byte VERSION = 1;
    private static final int IV_LENGTH = 12;
    private static final int TAG_BITS = 128;
    private static final int TAG_LENGTH = TAG_BITS / 8;
    /** magic + version + iv */
    public static final int HEADER_LENGTH = MAGIC.length + 1 + IV_LENGTH;

    /**
     * Encrypt {@code plaintext} into a self-describing envelope.
     *
     * @throws GeneralSecurityException the Keystore key is unavailable/invalid
     * @throws IOException              the Keystore could not be read/written
     */
    public byte[] encrypt(byte[] plaintext) throws GeneralSecurityException, IOException {
        byte[] data = plaintext == null ? new byte[0] : plaintext;
        SecretKey key = obtainKey();
        Cipher cipher = Cipher.getInstance(TRANSFORMATION);
        // The Android Keystore generates the IV itself; passing one for
        // encryption is rejected by the provider.
        cipher.init(Cipher.ENCRYPT_MODE, key);
        byte[] iv = cipher.getIV();
        if (iv == null || iv.length != IV_LENGTH) {
            throw new GeneralSecurityException("AES-GCM IV 长度异常");
        }
        byte[] ciphertext = cipher.doFinal(data);
        ByteBuffer envelope = ByteBuffer.allocate(HEADER_LENGTH + ciphertext.length);
        envelope.put(MAGIC);
        envelope.put(VERSION);
        envelope.put(iv);
        envelope.put(ciphertext);
        return envelope.array();
    }

    /**
     * Decrypt an envelope produced by {@link #encrypt(byte[])}.
     *
     * @throws GeneralSecurityException malformed envelope, tampered data or a key
     *                                  that no longer exists (device reset, key
     *                                  invalidation)
     */
    public byte[] decrypt(byte[] envelope) throws GeneralSecurityException, IOException {
        if (envelope == null || envelope.length < HEADER_LENGTH + TAG_LENGTH) {
            throw new GeneralSecurityException("加密存储数据长度无效");
        }
        for (int index = 0; index < MAGIC.length; index += 1) {
            if (envelope[index] != MAGIC[index]) {
                throw new GeneralSecurityException("加密存储数据标记无效");
            }
        }
        int version = envelope[MAGIC.length] & 0xFF;
        if (version != VERSION) {
            throw new GeneralSecurityException("加密存储数据版本不支持：" + version);
        }
        byte[] iv = Arrays.copyOfRange(envelope, MAGIC.length + 1, HEADER_LENGTH);
        Cipher cipher = Cipher.getInstance(TRANSFORMATION);
        cipher.init(Cipher.DECRYPT_MODE, obtainKey(), new GCMParameterSpec(TAG_BITS, iv));
        return cipher.doFinal(envelope, HEADER_LENGTH, envelope.length - HEADER_LENGTH);
    }

    /**
     * Whether {@code data} starts with this class' envelope magic. Used only to
     * produce a readable diagnostic for corrupt store files, never for trust.
     */
    public static boolean looksEncrypted(byte[] data) {
        if (data == null || data.length < HEADER_LENGTH) return false;
        for (int index = 0; index < MAGIC.length; index += 1) {
            if (data[index] != MAGIC[index]) return false;
        }
        return true;
    }

    /**
     * Drop the Keystore key so the next call generates a fresh one. Only useful
     * when the old key is unusable (invalidated) and the old ciphertext is
     * therefore unrecoverable anyway; the caller is about to write new data.
     */
    public void resetKey() throws GeneralSecurityException, IOException {
        KeyStore keyStore = KeyStore.getInstance(KEYSTORE_TYPE);
        keyStore.load(null);
        if (keyStore.containsAlias(KEY_ALIAS)) {
            keyStore.deleteEntry(KEY_ALIAS);
        }
    }

    /** Get (generating on first use) the non-exportable AES-256-GCM key. */
    private SecretKey obtainKey() throws GeneralSecurityException, IOException {
        KeyStore keyStore = KeyStore.getInstance(KEYSTORE_TYPE);
        keyStore.load(null);
        if (!keyStore.containsAlias(KEY_ALIAS)) {
            KeyGenerator generator = KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES, KEYSTORE_TYPE);
            generator.init(new KeyGenParameterSpec.Builder(
                    KEY_ALIAS,
                    KeyProperties.PURPOSE_ENCRYPT | KeyProperties.PURPOSE_DECRYPT)
                    .setKeySize(256)
                    .setBlockModes(KeyProperties.BLOCK_MODE_GCM)
                    .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE)
                    .setUserAuthenticationRequired(false)
                    .setRandomizedEncryptionRequired(true)
                    .build());
            generator.generateKey();
        }
        try {
            SecretKey key = (SecretKey) keyStore.getKey(KEY_ALIAS, null);
            if (key == null) throw new GeneralSecurityException("Android Keystore 密钥不可用");
            return key;
        } catch (UnrecoverableKeyException unrecoverable) {
            throw new GeneralSecurityException("Android Keystore 密钥无法恢复");
        }
    }
}
